bool InteropQuotes::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("transaction_code"))
    {
        if(!validJsonOfField(1, "transaction_code", pJson["transaction_code"], err, true))
            return false;
    }
    else
    {
        err="The transaction_code column cannot be null";
        return false;
    }
    if(pJson.isMember("quote_code"))
    {
        if(!validJsonOfField(2, "quote_code", pJson["quote_code"], err, true))
            return false;
    }
    else
    {
        err="The quote_code column cannot be null";
        return false;
    }
    if(pJson.isMember("account_id"))
    {
        if(!validJsonOfField(3, "account_id", pJson["account_id"], err, true))
            return false;
    }
    else
    {
        err="The account_id column cannot be null";
        return false;
    }
    if(pJson.isMember("amount"))
    {
        if(!validJsonOfField(4, "amount", pJson["amount"], err, true))
            return false;
    }
    else
    {
        err="The amount column cannot be null";
        return false;
    }
    if(pJson.isMember("fee_amount"))
    {
        if(!validJsonOfField(5, "fee_amount", pJson["fee_amount"], err, true))
            return false;
    }
    if(pJson.isMember("currency"))
    {
        if(!validJsonOfField(6, "currency", pJson["currency"], err, true))
            return false;
    }
    if(pJson.isMember("expiration"))
    {
        if(!validJsonOfField(7, "expiration", pJson["expiration"], err, true))
            return false;
    }
    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(8, "status", pJson["status"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(9, "created_at", pJson["created_at"], err, true))
            return false;
    }
    return true;
}
